window.TERRA_RACES={"meta":{"title":"泰拉种族专题","date":"2026-11-04","revision":"journey-races-20261104","entries":32,"scope":"《大地巡旅》第四章实际列出的32个具名种族主条目；不是全部游戏、联动族群或萨卡兹支系的穷尽名录。","printedPages":"079—106","sourceFile":"TERRA+A+JOURNEY.txt","sourceBytes":1214927,"sourceSha256":"00515b3aa0bd38983c4f785210b35865afa1441409765c81e31bb1c40c997f1b","sourceKind":"用户提供的官方设定集TXT转录；不是原版影印校样","method":"原创转述；区分作者论述、凯尔希批注、传说与个体见闻；不按耳角外观猜种族，不从族群统计反推个人年龄、寿命或具体技艺。","characters":10432},"overview":[{"title":"名称怎样形成","body":"《大地巡旅》把种族名称放在人类社会的发展中讨论。早期聚落、征服、人口迁徙与地方认同，参与塑造了今日的分类；相似的外貌不总意味着相同的历史，沿用同一称谓的人也可能拥有不同文化。本专题先交代能够核实的来源与变迁，再讨论当代生活，不为材料没有记载的族群补造一条完整年代轴。"},{"title":"先民与神民怎样理解","body":"先民、神民是泰拉历史与族群认识中的分类，不能直接等同于一个人的国籍、阶层或道德。书中以“供养—保护”模型解释部分古代社会，凯尔希批注又提醒，并非所有国家都经历过神民统治。梦魔远征和乌萨斯起义动摇了旧秩序，种族平等观念随后发展，但感染者所承受的不平等并未因此消失。"},{"title":"兽主、兽亲与族群不是一套分类","body":"兽主和其分离出的兽亲，并不是泰拉人先民、神民分类的另两个普通分支。书中批注以佩洛、狼之主等例子解释相互接触，也提醒读者：看到形似某种生物的个体，不能据外观确定其身份。专题与人物档案的关联，优先依据游戏本体公开的种族字段；未公开的记录继续保留未公开。"},{"title":"萨卡兹与王庭的范围","body":"萨卡兹是具有漫长共同历史的复杂族群称谓，王庭氏族只是其中一部分。书中还提到鬼、阿纳萨等非王庭氏族，而当代个体常具有混合血缘。本专题在萨卡兹篇下提供这些相关公开档案，卡片同时保留游戏原有登记，不把政治组织、血缘支系和个人身份合并成同一层级。"}],"entries":[{"id":"ursus","name":"乌萨斯","en":"Ursus","summary":"从北迁的族群到以族名命名的帝国，种族归属与国民身份在这段历史中交织。","relatedRegions":["ursus","kazimierz","kjerag","yan"],"profileNames":["乌萨斯"],"relatedNames":[],"sourceLines":[948,954],"sections":[{"title":"北迁与帝国建立","period":"早期迁徙至31年建国","body":"乌萨斯这个族名出现得早于乌萨斯帝国。按照《大地巡旅》的梳理，许多乌萨斯先民曾随黎博利骏鹰迁向北方，在严寒地区建立定居点，并长期处于骏鹰统治之下。梦魔远征动摇了旧王国，伊戈尔领导的起义随后将族群的劳动经验、军队联系与反抗力量汇集起来，最终建立以乌萨斯为名的帝国。\n\n这条历史线索能解释今天人口集中于帝国的局面，却不能把所有乌萨斯的迁徙都归入同一次行动。卡西米尔、谢拉格、炎国等地也有乌萨斯居民；其生活经验不必与帝国本土相同。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·乌萨斯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第948—954行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"族名与国民认同","period":"帝国形成以后","body":"高大、耐寒、力量较强，是书中概括的群体特征；北方漫长冬季也参与塑造了坚忍的自我形象。这些概括并非每个个体的体检结果，更不能直接推导职业、政治立场或性格。\n\n书中特别区分乌萨斯种族与乌萨斯民族：前者描述族群，后者包含国民认同。非乌萨斯种族的人可以认同帝国，而出生于其他国家的乌萨斯也不因族名自动具有帝国国籍。阅读早露、凛冬等人的经历时，需要继续看家庭、阶层和具体事件，而不能以一种共同的外貌替代个人历史。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·乌萨斯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第948—954行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·乌萨斯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第948—954行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"feline","name":"菲林","en":"Feline","summary":"分布广泛、内部差异显著的庞大族群，维多利亚的迁徙史只是其中一条支线。","relatedRegions":["victoria","sargon","kjerag"],"profileNames":["菲林"],"relatedNames":[],"sourceLines":[955,960],"sections":[{"title":"广泛分布与迁徙","period":"古代迁徙至现代混居","body":"菲林与佩洛、黎博利同属书中讨论的人口庞大、分布广泛的族群。尖耳、长尾和较敏锐的感官是常见特征，但耳形、尾长与遗传表现并不一致。“菲林”因而不能被简化成一种固定形貌，更没有一套适用于所有地区的生活方式。\n\n在维多利亚，许多菲林家系与阿斯兰远征及其后长期通婚、定居有关。追随阿斯兰而来的居民与德拉克统治时期的当地居民相处，逐渐形成新的家庭和社会关系。这个过程解释了部分人口的来源，并不代表当地每位菲林都能据此确认自己的祖籍。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·菲林（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第955—960行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"名称与地方身份","period":"族群分类逐渐细化以后","body":"古代对菲林的认识曾广泛依赖外貌；阿斯兰形成独立称谓后，其他群体也尝试用新的名字确立自身身份。书中借此说明，种族分类同权力、迁徙与自我认同有关，并非一开始就完整存在。\n\n在现代多族混居的环境里，菲林的个人身份更多通过家乡、职业、家族和共同生活建立。银灰、杰西卡与海蒂拥有相同的公开种族登记，却处在不同制度和社会关系中。个别特殊人物的档案登记也不能代替其全部身世，相关经历应继续回到人物纪事核对。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·菲林（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第955—960行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·菲林（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第955—960行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"aslan","name":"阿斯兰","en":"Aslan","summary":"阿斯兰的独立称谓与征服、王权和族群自我认知的变化相连。","relatedRegions":["sargon","victoria"],"profileNames":["阿斯兰"],"relatedNames":[],"sourceLines":[961,966],"sections":[{"title":"征服与独立称谓","period":"部落时代的阿斯兰征服","body":"《大地巡旅》把阿斯兰称谓的形成放在部落兼并的历史中。书中认为，阿斯兰在生物分类上与菲林非常接近，其作为独立种族被社会承认的过程，却与强大统治集团的征服和政治影响直接相关。阿斯兰不只占领土地，也使自身关于族群边界的认识传播到其他地区。\n\n作者以此解释现代种族名称如何逐渐细分。这是书中的历史论述，不能反过来把一切族群分类都归因于某次战争，也不能把生物关系近似写成所有个人能力完全相同。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·阿斯兰（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第961—966行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"萨尔贡与维多利亚的家系","period":"阿斯兰向维多利亚迁徙以后","body":"如今阿斯兰人口稀少，主要同萨尔贡和维多利亚的贵族、王室历史联系在一起。两地的阿斯兰属于不同家系，而非书中另行划出的两个种族分支。迁往维多利亚的支系介入德拉克王权，最终改变了帝国的统治结构。\n\n阿斯兰的力量与历史地位并不能保证每位成员具有同一种命运。维娜的人物纪事需要从王室覆亡、离开宫廷及她与城市居民的关系继续读起；种族身份只能交代其中一部分背景。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·阿斯兰（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第961—966行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·阿斯兰（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第961—966行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"perro","name":"佩洛","en":"Perro","summary":"从古代宽泛称呼到现代分类，佩洛的历史也记录了人们如何重新划分相似族群。","relatedRegions":["bolivar","sargon","sami","higashi"],"profileNames":["佩洛"],"relatedNames":[],"sourceLines":[967,977],"sections":[{"title":"古代称呼与分化","period":"族群命名逐渐细化的时期","body":"佩洛广泛分布于泰拉，玻利瓦尔是人口集中的地区之一。书中说明，在非常早的分类观念中，后来被称为鲁珀、沃尔珀、瑞柏巴的一些群体曾与佩洛共同生活，也曾被归入同一称谓。其后，生理认识和自我认同发生变化，新的分类逐渐形成。\n\n这段历史不意味着现代分类毫无区别，也不意味着只凭耳朵和尾巴便能准确辨认族群。佩洛本身还包含神民与先民的若干分支，外来者往往无法从日常接触中分清。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·佩洛（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第967—977行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"家族传统与生活环境","period":"长期形成的聚落文化及现代生活","body":"传统佩洛聚落常把范围较大的共同体视作同一家族，维持人际关系与互助因而受到重视。书中把这种文化同大型家庭生活联系起来，但没有把友善当作所有佩洛必须具有的性格。不同国家的战争、教育和劳动环境仍会改变个人经历。\n\n书中还以玻利瓦尔的“猎犬”传闻说明偏见与证据的差别：作者未能证实的人体实验说法不能直接当作事实；批注另从兽主与战争兵器的角度提出解释。佩洛、兽亲及训练用猎犬也不因此成为可以互换的称呼。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·佩洛（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第967—977行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·佩洛（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第967—977行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"lupo","name":"鲁珀","en":"Lupo","summary":"叙拉古的家族政治深刻影响了鲁珀文化，兽主与人类的关系又构成另一层历史。","relatedRegions":["siracusa","victoria","ursus"],"profileNames":["鲁珀"],"relatedNames":[],"sourceLines":[978,987],"sections":[{"title":"叙拉古与家族秩序","period":"古老聚落至家族城邦形成","body":"鲁珀以叙拉古为主要聚居地，也生活在乌萨斯、维多利亚等国。其生理特征与佩洛接近，分类的历史却很早就分开了。书中将鲁珀的家族认同，同叙拉古森林中的生存压力、聚落竞争和长期的家族边界联系起来。\n\n一些家族以尾毛染色或耳尖标记表明归属，后来这些标识又进入更复杂的社会等级。家族可以提供保护，也可能要求服从、制造排外；不能把某一地区的家族规范直接当作全体鲁珀不可改变的天性。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·鲁珀（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第978—987行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"兽主影响与个人选择","period":"家族文化延续至现代","body":"《大地巡旅》的批注指出，叙拉古活跃的狼之主会选择代理人，把人类卷入兽主间的争斗。书中把这种关系视作家族文化成形的重要背景，但狼之主、其兽亲群体与普通鲁珀居民属于不同概念。\n\n鲁珀的肢体表达也受教育和环境影响。在大家族中成长者可能被训练控制耳尾动作，以免泄露情绪；这并不表示所有鲁珀都没有相应动作或感情。德克萨斯、拉普兰德、伺夜与斥罪对家族的不同回应，应放在各自经历中理解。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·鲁珀（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第978—987行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·鲁珀（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第978—987行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"vulpo","name":"沃尔珀","en":"Vulpo","summary":"从斥候与信使的古老职业传统，到跨族开放的尾巴护理活动，沃尔珀的文化随环境变化。","relatedRegions":["siracusa","higashi","sargon"],"profileNames":["沃尔珀"],"relatedNames":[],"sourceLines":[988,994],"sections":[{"title":"辨认、分布与职业传统","period":"古代部落至现代佣兵和信使组织","body":"沃尔珀的生理差异常被外来者忽略，因而容易被误认作佩洛，连人口分布统计也受到影响。书中指出，沃尔珀在各地所占人口比例通常不高；这种分散格局使其生活方式难以用单一地区概括。\n\n较好的反应和环境感知，使部分沃尔珀自古成为斥候与信使。现代佣兵和运输工作仍延续了这些联系，但职业经验、训练和个人条件同样重要，不能仅凭种族登记认定某人必然擅长潜行或侦察。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·沃尔珀（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第988—994行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"分支与尾部文化","period":"长期形成的地方传统","body":"书中同时记载神民和先民分支，东国的九尾沃尔珀是广为人知的一例。关于其与上层家族的关系，作者明确保留了未知，并未提供完整家系。不能把九尾特征或他人传闻直接转成个人的政治身份。\n\n叙拉古部分沃尔珀重视尾部护理，家庭聚会中的礼仪后来发展为开放其他族群参与的比赛。这个例子体现的是地方文化如何变成公共活动，而非全部沃尔珀都必须遵循的统一风俗。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·沃尔珀（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第988—994行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·沃尔珀（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第988—994行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"reproba","name":"瑞柏巴","en":"Reproba","summary":"以萨尔贡为主要生活地区，荒地经验、女性主导的大家族和军旅传统相互联系。","relatedRegions":["sargon","bolivar"],"profileNames":["瑞柏巴"],"relatedNames":[],"sourceLines":[995,1002],"sections":[{"title":"从古老称呼到独立分类","period":"部落时代至分类观念形成","body":"瑞柏巴人口较少，主要生活在萨尔贡。书中把其祖先放在早期佩洛的宽泛称谓之内，指出他们某些古老习俗曾引来非议；漫长的变化之后，瑞柏巴才以独立称呼进入后来的分类。\n\n这种被外界区分和议论的历史，也使一些瑞柏巴格外排斥旁人以传闻联系他们与萨卡兹。作者没有将相关恐怖故事当作族群本性，今日的分类与个人也不应承担旧传闻强加的评价。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·瑞柏巴（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第995—1002行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"荒地家庭与走向外地","period":"长期形成的生活传统及近代迁徙","body":"萨尔贡一些瑞柏巴部族由女性大家长组织，重视家庭内部的纪律和协作。荒地求生、放牧与军旅经验，构成其生活传统的一部分。书中也提到抵抗梦魔军队的女战士传说，这属于族群历史记忆，不能据此补出每一支部族的战斗记录。\n\n近年来更多瑞柏巴离开祖辈聚落，在牲畜饲养、野外调查等工作中使用荒地经验。迁居不代表传统原样复制；斑点、豆苗等人的职业和家庭关系，应根据各自公开档案分别阅读。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·瑞柏巴（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第995—1002行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·瑞柏巴（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第995—1002行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"liberi","name":"黎博利","en":"Liberi","summary":"羽毛特征下包含许多差异显著的群体，国别、迁徙与职业往往比一个总称更能解释个人经历。","relatedRegions":["columbia","iberia","laterano","ursus"],"profileNames":["黎博利"],"relatedNames":[],"sourceLines":[1003,1009],"sections":[{"title":"广泛称谓与迁徙","period":"古代分布至哥伦比亚移民潮","body":"黎博利是一个涵盖范围很广的称谓，既包含先民，也包括骏鹰等神民分支。羽毛的分布和其他生理特征并不一致；拥有某些共同外貌，并不能说明所有黎博利出自同一地方或具有相同能力。\n\n哥伦比亚建国后吸引大量移民，黎博利也随之迁入。书中提及，重新开始生活的机会与黎博利总统的公共形象共同构成吸引力。伊比利亚、拉特兰等地同样有大量黎博利，其历史没有因此被纳入联邦的一条迁徙线。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·黎博利（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1003—1009行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"地方文化与分类争论","period":"现代多族社会","body":"由于人口庞大且分布广，书中没有为黎博利指定一套共同的文化。有学者主张进一步拆分分类，也有人提醒不要把文化差别直接等同于生物分类。这个争论本身说明：同一总称内部可以容纳不同的社会生活。\n\n伊比利亚审判庭成员、拉特兰的非萨科塔居民与哥伦比亚研究者，面对的制度和关系并不相同。菲亚梅塔的处境、赫默的研究及艾丽妮的职责，都需要通过相关人物和地区纪事继续核对。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·黎博利（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1003—1009行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·黎博利（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1003—1009行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"cautus","name":"卡特斯","en":"Cautus","summary":"从应对天灾的屯堡大家庭，到矿业联合体，聚居和互助始终参与塑造卡特斯的生活。","relatedRegions":["rim","ursus"],"profileNames":["卡特斯","卡特斯/奇美拉"],"relatedNames":[],"sourceLines":[1010,1016],"sections":[{"title":"屯堡与联合家庭","period":"部落时代的雷姆必拓","body":"卡特斯广泛生活于雷姆必拓，在其他国家也不罕见。长耳、短尾和较敏捷的反应是常见特征；书中没有把这些特征视作能够独自战胜环境的条件。对于早期聚落，群体协作同样不可缺少。\n\n雷姆必拓的卡特斯共同耕作、寻找矿脉，并建造可躲避部分天灾的半地下屯堡。联合家庭成为维系聚落的核心，成员需要在劳动、居住和避难中相互配合。这个社会结构比现代矿业公司出现得更早。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·卡特斯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1010—1016行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"互助传统的延续与改变","period":"结晶时代以来","body":"外出冒险、在异乡组成新家庭，在许多卡特斯社区中能够得到支持，因为它也有助于让原有屯堡维持合适的人口规模。家庭认同因此不只意味着留守，还包含帮助离乡者开始新的生活。\n\n源石工业发展后，矿业联合体承接了部分旧有社区的生产与组织功能。书中据此解释雷姆必拓人在围栏事件中抵抗外来压力的社会基础。现代干员的档案有时另列复合登记；例如阿米娅的“卡特斯/奇美拉”必须保留原字段，不能为了专题分类而抹去其中一项。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·卡特斯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1010—1016行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·卡特斯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1010—1016行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"kuranta","name":"库兰塔","en":"Kuranta","summary":"平原迁徙、骑士家族与梦魔远征，共同构成库兰塔分布和军事文化的历史。","relatedRegions":["kazimierz","sargon"],"profileNames":["库兰塔"],"relatedNames":[],"sourceLines":[1017,1023],"sections":[{"title":"平原生活与远征后的分散","period":"古代定居至梦魔远征以后","body":"库兰塔的祖先在卡西米尔平原活动，迁徙和防卫需求推动了全民习武的传统。并非所有库兰塔都始终留在当地：梦魔可汗远征时，一些族群随军离开，远征结束后又在大地各处定居。\n\n库兰塔包括神民与先民分支。天马和梦魔之间的战争改变了卡西米尔的统治格局，但这两支不能代表全部库兰塔。书中没有给每一个现代家系补出同样的远征履历，相关血统与先后仍须以个人材料为准。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·库兰塔（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1017—1023行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"家族、长骑与现代骑士","period":"骑士政权建立至竞技商业化","body":"在经常变换居所的生活中，家庭比固定地点更能维持连续关系，长骑因而承担了组织家族的职责。现代卡西米尔的社会已深受城市生活和商业影响，骑士协会仍保留有关长骑的制度。\n\n体能与军事传统不能解释现代骑士生活的全部。征战骑士、竞技骑士、感染者参赛者和普通劳动者，承受的制度要求并不一样。临光家族、白金和焰尾的故事，分别呈现了血统、雇佣关系及身份限制如何改变同一社会中的人。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·库兰塔（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1017—1023行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·库兰塔（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1017—1023行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"forte","name":"丰蹄","en":"Forte","summary":"常被简化成力量象征的丰蹄，也保留着哲学、农耕与因地制宜的运输传统。","relatedRegions":["minos","yan","sargon"],"profileNames":["丰蹄"],"relatedNames":[],"sourceLines":[1024,1030],"sections":[{"title":"米诺斯与思想传统","period":"古代城邦时期","body":"丰蹄以米诺斯为主要聚居地，也广泛生活在炎国、萨尔贡等地。强壮的形象常被商业宣传放大，书中却特别指出，部分丰蹄社区更重视智慧、文艺和思想讨论，不能把体能当作唯一特征。\n\n米诺斯的思想家费那拉底被记为丰蹄，她与一位来自萨尔贡的菲林讨论哲学。现存材料没有完整保留下她们的体系，但一些问题延续到后来的讨论之中。人物贡献由其行动构成，不能简单归结为种族能力。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·丰蹄（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1024—1030行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"农耕、运输与迁移","period":"长期形成的生产生活","body":"炎国的丰蹄族群与早期农耕生活联系密切。面对劳动强度和天灾风险，固定耕地并不意味着永久定居；有关适应崎岖道路运输车的传统，体现了在不同土地间转移和留出休耕时间的经验。\n\n现代丰蹄仍从事多种职业，劳动者形象不应被误作全体成员的身份。帕拉斯的信仰与经历、拜松的物流工作和火神的工艺，分别连接了不同地方的教育、生产与个人选择。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·丰蹄（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1024—1030行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·丰蹄（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1024—1030行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"caprinae","name":"卡普里尼","en":"Caprinae","summary":"对术法和音乐的热爱与莱塔尼亚历史相连，群体适应性并不等于每个人都能施术。","relatedRegions":["leithanien","sargon"],"profileNames":["卡普里尼"],"relatedNames":[],"sourceLines":[1031,1036],"sections":[{"title":"分布与术法认识","period":"长期形成的族群分布","body":"卡普里尼主要集中于莱塔尼亚及其周边，也生活在泰拉其他地区。书中概括其平均源石技艺适应性较好，同时明确提醒，仍有无法使用源石技艺的卡普里尼个体。群体统计不能代替个人档案测试，更不等同于某一种固定的施术形式。\n\n莱塔尼亚在音乐和术法领域形成的传统，与当地卡普里尼人口有关，但文化还受到贵族制度、教育机关和历史战争影响。不能把高塔政治或音乐训练都写成与生俱来的生理本能。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·卡普里尼（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1031—1036行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"角的审美与不同生活","period":"地方文化延续至现代","body":"爱护头上的角，是书中记录的一种显著审美习惯。这种兴趣也延伸到其他有角族群；审美可以跨越种族边界，却不改变各族自身的生理差别。\n\n卡普里尼在不同地区形成不同的学习和谋生道路。艾雅法拉的地质研究、黑键面对的家族与音乐传统、卡涅利安姐妹的离乡经历，均须回到各自材料。尤其不能从术法适应性推出个人年龄、寿命或必然的疾病结局。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·卡普里尼（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1031—1036行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·卡普里尼（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1031—1036行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"elafia","name":"埃拉菲亚","en":"Elafia","summary":"萨米的迁徙与自然文化影响深远，但“森林之子”的文学形象不能概括所有埃拉菲亚。","relatedRegions":["sami","ursus","kazimierz","leithanien"],"profileNames":["埃拉菲亚"],"relatedNames":[],"sourceLines":[1038,1055],"sections":[{"title":"萨米来源与向外迁徙","period":"早期分布至现代城市扩张","body":"萨米是埃拉菲亚的重要聚居地区，乌萨斯、莱塔尼亚、卡西米尔等地也有大量居民。书中把许多外地群体的来源联系到萨米，却没有据此说明每个家族的具体迁徙年代。城市扩张之后，一些人已不再沿袭林地游猎生活。\n\n文学作品常因分叉角和林地生活，将其塑造成天然亲近森林的人。作者指出，这种形象混合了生理特征与萨米地方文化；居于现代城市的埃拉菲亚并不因此必须具有相同信仰或生活习惯。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·埃拉菲亚（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1038—1055行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"角与地方交流传统","period":"族群成长及地方仪式","body":"埃拉菲亚的角在部分成长阶段会有皮肤和神经分布，因此以角接触对一些群体具有特殊的情感与交流意义。萨米部分部族还将角视作感知自然的媒介，这种认识与当地祭司和宗教传统相连。\n\n书中描述的具体生理阶段与仪式不能推广为所有成员终身一致的情况。读守林人、薇薇安娜或仇白时，需要区分其成长环境、家族关系和个人训练，不把角的形状当作职业或思想的证明。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·埃拉菲亚（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1038—1055行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·埃拉菲亚（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1038—1055行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"vouivre","name":"瓦伊凡","en":"Vouivre","summary":"从阿斯兰统治下的自治领地，到护卫与佣兵传统，瓦伊凡的迁徙与政治关系相伴。","relatedRegions":["sargon","victoria"],"profileNames":["瓦伊凡"],"relatedNames":[],"sourceLines":[1064,1068],"sections":[{"title":"征服、分封与迁徙","period":"阿斯兰征服及其后","body":"瓦伊凡主要生活在萨尔贡、维多利亚及瓦伊凡联盟控制地区。书中将其部分迁徙追溯到阿斯兰征服：瓦伊凡战败后获承认，保有领地，并成为王室护卫；后来一些人又随阿斯兰支系前往维多利亚。\n\n外貌与德拉克相近，并不代表两者可互换。书中讨论了技艺适应性的群体差异，但这些差异不能代替任何人的档案或训练成果。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·瓦伊凡（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1064—1068行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"自治领与佣兵道路","period":"近代工业化及现代生活","body":"萨尔贡北部瓦伊凡部落长期具有较高自治权，现代又联合建造小型移动城市，寻求进一步改变与帝国的关系。书中记录的是特定时点的政治状况，不据此认定后来的争议已经解决。\n\n部分传统社区从年轻一代中选拔、训练宫廷护卫，未获选者往往走向佣兵工作，这构成军旅传统的一条来源。现代的塞雷娅、风笛、琴柳等人分属不同职业和制度，不能因相同族群而视为同一支武装的延续。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·瓦伊凡（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1064—1068行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·瓦伊凡（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1064—1068行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"manticore","name":"曼提柯","en":"Manticore","summary":"萨尔贡偏远聚落保留着低调生活传统，外界的神秘传说往往掩盖了普通居民的日常。","relatedRegions":["sargon"],"profileNames":["曼提柯"],"relatedNames":[],"sourceLines":[1069,1086],"sections":[{"title":"偏远聚落与居住选择","period":"移动城市出现前后","body":"曼提柯十分少见，主要居于萨尔贡。膜状翼和节肢状尾部是书中介绍的常见特征，部分个体尾针有毒，但书中没有把这些身体差异等同于敌意。\n\n移动城市兴起后，一些曼提柯仍选择在偏远地区维持聚落生活。作者的研究团队曾拜访其中一处，在解释来意后得到接待。这是一份具体走访记录，能说明聚落并非完全拒绝交流，却不足以代表所有曼提柯社区。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·曼提柯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1069—1086行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"隐蔽传统与外部误解","period":"长期形成的地方文化","body":"低调、隐蔽的生活方式使外人知之甚少，也给污蔑性故事留下空间。书中明确区分了居民生活与“食人者”等恐怖传闻：未知不构成指控的证据。\n\n因此，狮蝎的隐匿能力、交往困难及后来建立的关系，需要依据她的个人档案阅读；不能由族名反推其成长经历，或把一位干员的特质写成全族相同的源石技艺。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·曼提柯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1069—1086行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·曼提柯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1069—1086行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"phidia","name":"斐迪亚","en":"Phidia","summary":"人口分散、缺少统一聚居模式的斐迪亚，常被文学偏见赋予缺乏依据的形象。","relatedRegions":["sargon","victoria","sami","ursus"],"profileNames":["斐迪亚"],"relatedNames":[],"sourceLines":[1087,1093],"sections":[{"title":"分散居住与外部形象","period":"长期分布至现代生活","body":"斐迪亚人数相对较少，却分布于多种环境，并没有书中能够归纳出的统一聚居区域。鳞尾等常见特征让外人容易以别名称呼他们，文学又反复将其描绘为瘦弱、多疑或情绪不稳。作者明确指出，这些印象缺少依据。\n\n书中还澄清，绝大多数斐迪亚没有毒，也不依靠传闻中的方式行动。身体特征不应被当作某种危险行为的预告。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·斐迪亚（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1087—1093行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"职业经验与个人材料","period":"作者当代见闻","body":"作者举出专注于铁路信号研究和竞技资料整理的熟人，讨论长期投入某项事业的经验。他同时承认这是有限的个人观察，不能视作对全体斐迪亚的能力测试。\n\n森蚺的机械实践、深靛的学习和暮落的经历，具有不同的家庭与环境背景。专题用这些档案建立阅读入口，不以几则见闻替他们补写共同祖先、统一习俗或相同施术能力。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·斐迪亚（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1087—1093行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·斐迪亚（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1087—1093行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"savra","name":"萨弗拉","en":"Savra","summary":"沙漠与荒地经验构成常见生活背景，长寿者的具体经历也被传说过度放大。","relatedRegions":["sargon","rim","victoria"],"profileNames":["萨弗拉"],"relatedNames":[],"sourceLines":[1103,1107],"sections":[{"title":"荒地生活与迁居","period":"长期居住及现代人口流动","body":"萨弗拉以萨尔贡为主要生活地区，也有部分人口迁居雷姆必拓等地。书中记录了敏锐视力、鳞片与环境适应的关系；某些个体能够改变鳞片颜色，但不能把这一表现直接等同于所有人的源石技艺。\n\n沙漠和荒地提供了经验，也使外界喜欢以老猎人的形象概括整个族群。这类人物模板经由故事流传，逐渐掩盖了实际生活中的差别。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·萨弗拉（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1103—1107行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"寿命记述与个体差异","period":"作者记录的当代人物","body":"书中确实提到萨弗拉较长的寿命，并举出年逾一个半世纪、仍服务地方议会的昂斯特先生。这是具名个案，不是全族统一的寿命上限，也不能用于反推一位未公开年龄干员的岁数。\n\n长期生活带来的见闻可能影响职业和思考，巡林者、伊桑、石棉等人的道路仍各不相同。专题保留族群层面的记载，个人能力、年龄与医疗状况继续以各自档案为准。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·萨弗拉（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1103—1107行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·萨弗拉（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1103—1107行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"zalak","name":"札拉克","en":"Zalak","summary":"广泛迁徙的札拉克在信使、城镇劳动和影视传播中呈现出多种生活面貌。","relatedRegions":["kazimierz","kjerag","columbia","rim"],"profileNames":["札拉克"],"relatedNames":[],"sourceLines":[1108,1118],"sections":[{"title":"广泛分布与职业变化","period":"传统迁徙至现代城市生活","body":"札拉克人口众多，泰拉许多地区都有聚落。毛发、耳簇和尾部形态随支系与环境呈现差别，书中并没有将一类外貌视作统一族群的全部样貌。\n\n较灵敏的听觉与反应，使部分札拉克从事信使、天灾信使等工作。城市和交通网络变化后，职业选择继续增加；现代公开档案中的多萝西、林和洋灰，便不能用同一种传统职业概括。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·札拉克（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1108—1118行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"社会印象与影视传播","period":"近代移民与1094年后的文化传播","body":"书中记录哥伦比亚影视作品对札拉克公共形象的影响：一些作品把受到轻视的储备行为重新解释为替家庭作准备，随后又与拓荒宣传结合，吸引新的移民。\n\n这一例子描述的是舆论和商业如何塑造族群印象，不证明所有札拉克有相同习惯。迁居荒地的劳动者、留在原乡的人和城市研究者，都需要在各自的制度与人生经历中理解。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·札拉克（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1108—1118行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·札拉克（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1108—1118行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"durin","name":"杜林","en":"Durin","summary":"分布在地下的城邦各具文化，先进技术与相对独立的社会生活并存。","relatedRegions":["durin","sargon"],"profileNames":["杜林"],"relatedNames":[],"sourceLines":[1119,1123],"sections":[{"title":"地下城邦与有限记录","period":"长久地下生活至近百年的外部研究","body":"杜林人的居住地广布于地下，以城邦为重要社会单位。不同城市的生活方式与文化并不一致，但存在保持交流的办法。书中认为，用于建设与维护地下城市的许多技术已相当先进。\n\n外部文献虽早有杜林活动记录，对其社会的了解却长期零散。身材较小不是疾病后遗症，作者明确反对把未经证实的医学猜想当作族群解释。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·杜林（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1119—1123行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"走向地表与彼此交往","period":"个别迁居及现代接触","body":"一些杜林人主动到地表生活，很少向外人详述家乡。书中没有据此宣布整个族群拥有同一种对外政策，更没有把先进技术写成必然干预地表的理由。\n\n桃金娘、褐果、至简和其他人的公开档案，是继续理解个体的入口。际崖城与阿卡胡拉之间的故事展示了一次具体接触和迁移，不能被扩大为所有地下城市同时发生的统一行动。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·杜林（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1119—1123行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·杜林（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1119—1123行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"cerato","name":"塞拉托","en":"Cerato","summary":"绿洲聚落的生活经验、对角的重视和羽兽饲养，构成书中记录的塞拉托文化。","relatedRegions":["sargon"],"profileNames":["塞拉托"],"relatedNames":[],"sourceLines":[1135,1139],"sections":[{"title":"绿洲生活与向外迁居","period":"萨尔贡传统聚居及近百年迁徙","body":"塞拉托原先主要生活在萨尔贡绿洲，近百年来更多人在外地活动。强健体格和奔跑能力是书中常见描述，但短程奔跑与长途迁徙并不是同一件事；作者同时转述了重体型可能增加长途行动消耗的地方解释。\n\n这类群体认识不能代替个人体检，儿童与成年人也不应混用同一种力量标准。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·塞拉托（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1135—1139行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"角与聚落日常","period":"长期形成的生活传统","body":"塞拉托重视角的坚韧，部分社区通过短途对冲磨砺角，也有人给角加装护具。这些竞技和训练有其地方语境，不宜把外观激烈的活动直接解释成族群间的敌对。\n\n羽兽饲养是书中记录的另一项绿洲传统，包含日常陪伴和社区生活。泡泡的成长故事应由她自己的档案补足，不能从角或出身便认定她已具备所有成年战士的经验。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·塞拉托（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1135—1139行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·塞拉托（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1135—1139行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"anura","name":"安努拉","en":"Anura","summary":"雨林中的规划、建造协作和技艺传承，比外界对毒性的想象更接近实际生活。","relatedRegions":["sargon","bolivar"],"profileNames":["安努拉"],"relatedNames":[],"sourceLines":[1140,1155],"sections":[{"title":"雨林居住与外界接触","period":"古代聚落至现代迁居","body":"安努拉较为少见，主要生活在萨尔贡和玻利瓦尔的湿润地区。偏远聚落与较少人口使外人接触有限，萨尔贡宫廷因而长期以智慧、神秘等形象想象他们，并邀请部分人任职。\n\n这反映宫廷的认识与用人传统，并不能证明每位安努拉都具有相同的知识或社会地位。现代迁入城市者也有各自的居住需求和职业。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·安努拉（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1140—1155行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"社区协作与技艺边界","period":"长期形成的雨林生活","body":"书中记录安努拉同阿达克利斯的互助：一方参与居所建设，另一方提供规划和装饰等工作，双方还通过游泳比赛交往。相关技艺在生产生活中传承，并不只有战斗用途。\n\n部分安努拉能够使用毒素，但作者明确反对把接触安努拉等同于必然中毒。蓝毒的医疗、交往及能力材料，应按个人档案阅读；不能把一个人的毒性、施术形式或防护要求推广到所有同族。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·安努拉（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1140—1155行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·安努拉（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1140—1155行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"archosauria","name":"阿达克利斯","en":"Archosauria","summary":"雨林沿河聚落的力量传统，始终同水中行动、社区竞技和地方认同相连。","relatedRegions":["sargon","durin"],"profileNames":["阿达克利斯"],"relatedNames":[],"sourceLines":[1156,1160],"sections":[{"title":"沿河聚落与提亚卡乌认同","period":"萨尔贡古老聚落时期","body":"阿达克利斯主要生活在萨尔贡东部湿润雨林，许多社区沿河建立。善于游泳和水中行动影响了捕猎、防卫与居住选择，外人若只注意地面上的力量，便容易忽略其水中活动经验。\n\n部分阿达克利斯以“提亚卡乌”自称。书中将这一认同同古代对勇士的封赏相联系，但它具有地方历史语境，不能无差别替换每位阿达克利斯的种族登记或国籍。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·阿达克利斯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1156—1160行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"竞技与文化交流","period":"传统活动及近代变化","body":"尾部竞技常用拖拽原木等方式比较力量，也包含许多不同项目。近代外来球类活动进入后，部分年轻人又发展出以尾部控球的比赛，显示传统并非静止不变。\n\n嘉维尔、特米米与艾丝黛尔具有不同的成长经历。前两人与阿卡胡拉的关系，可以在地区篇继续读；人物能力则须区分个人训练、装备和源石技艺，不把力量或游泳天赋直接写成统一的施术能力。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·阿达克利斯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1156—1160行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·阿达克利斯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1156—1160行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"itra","name":"依特拉","en":"Itra","summary":"高寒山地的生活与谢拉格宗教文献传统，共同构成书中有限但具体的记录。","relatedRegions":["kjerag","yan","ursus","sami"],"profileNames":["依特拉"],"relatedNames":[],"sourceLines":[1161,1179],"sections":[{"title":"高寒地区的聚居","period":"长期形成的山地分布","body":"依特拉主要生活在高原、山地或冰原附近，在炎国、谢拉格、乌萨斯和萨米均有分布。书中通过身体差异讨论其与若干近似外貌族群的区分，但没有将外观观察当作完整的个体身份鉴定。\n\n危险环境使一些聚落保留较强的警惕和边界意识。这是地方生活的历史经验，不应被转成每位依特拉必然拒绝交往的性格结论。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·依特拉（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1161—1179行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"宗教文献与现代职业","period":"谢拉格信仰传播至现代生活","body":"书中认为谢拉格依特拉是较早参与耶拉冈德信仰的族群之一，并曾在经文、典籍的编纂传播中起重要作用。这说明其文化贡献并不限于外界注意到的山地生存能力。\n\n讯使的人物档案连接了当代谢拉格的信使工作与社会关系。该职业由个人经历与训练形成，不能据其一人倒推出所有依特拉的生活，也不能替书中未明确的迁徙年代补上年份。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·依特拉（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1161—1179行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·依特拉（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1161—1179行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"petram","name":"匹特拉姆","en":"Petram","summary":"水源附近的隐居聚落保存着独特工艺，对外接触的记录仍然有限。","relatedRegions":["yan","victoria","iberia"],"profileNames":["匹特拉姆"],"relatedNames":[],"sourceLines":[1180,1187],"sections":[{"title":"稀少记录与隐居聚落","period":"古代记载至作者走访","body":"匹特拉姆极少进入公众视野，书中甚至提到部分研究者因材料不足而怀疑其存在。作者记录的聚落多位于水源丰富之处，并强调外貌缺少常被用来识别族群的明显特征。\n\n缺乏知识不等于这个群体没有历史。古萨尔贡史料已经提到其材料与工艺，只是技术细节很少被外人掌握。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·匹特拉姆（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1180—1187行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"工艺传承与未解关系","period":"地方生产传统及当代交流","body":"部分匹特拉姆聚落保存熔炼和材料加工经验，出产物受到周边统治者重视，却未必愿意交出知识。相关能力来自具体的生产与传承，不能自动视为所有人的源石技艺。\n\n作者在炎国、维多利亚和伊比利亚沿海观察到一些匹特拉姆与上岸阿戈尔关系亲近，但学界解释尚未形成结论。蛇屠箱的个人档案可作另一阅读入口，专题不把尚无定论的联系写成已证实的统一族源。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·匹特拉姆（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1180—1187行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·匹特拉姆（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1180—1187行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"anaty","name":"阿纳缇","en":"Anaty","summary":"山地行走、信使工作和依山而建的居所，体现了环境与生活技术之间的联系。","relatedRegions":["kjerag","yan"],"profileNames":["阿纳缇"],"relatedNames":[],"sourceLines":[1188,1200],"sections":[{"title":"山地生活与交通工作","period":"传统山区生活至移动城市时代","body":"阿纳缇是较常见的族群，许多群体长期生活于山区。熟悉崎岖道路使部分人从事行商与信使工作，移动城市发展后，这些职业经验又被带进城际交通网络。\n\n书中没有据此提供一个覆盖所有支系的起源地或迁徙年表。山区居住也不等于每位现代阿纳缇都亲历了同一种成年考验。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·阿纳缇（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1188—1200行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"居住技术与成年习俗","period":"部分偏远聚落的传统","body":"一些社区仍在山壁开凿洞穴式居所，以挖掘和利用地形代替大量地表建造；部分聚落还保留让年轻人在野外独立生存一段时间的成年礼。作者把这些实践置于应对环境的经验之中。\n\n它们不是全体阿纳缇今日必须遵循的制度。罗宾、梅尔、罗比菈塔等人的劳动与知识来自不同环境，应由个人经历说明，不能用山地传统替代其教育和职业史。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·阿纳缇（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1188—1200行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·阿纳缇（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1188—1200行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"pilosa","name":"皮洛萨","en":"Pilosa","summary":"公开材料稀少，认识这一族群尤其需要分清现场记录、艺术作品与个体见闻。","relatedRegions":["rim","higashi"],"profileNames":["皮洛萨"],"relatedNames":[],"sourceLines":[1201,1214],"sections":[{"title":"有限材料与分类困难","period":"长久零散记载至当代调查","body":"作者承认自己没有亲眼辨认过皮洛萨，长期搜集的资料也很少。书中收录这一条，依据的是历史上确有相关记载，而非已经完成全面的社会调查。\n\n1053年的矿场安全报告和后来的人事补充提供了具体个案，但个体的迟缓表现不足以说明全族的能力与职业。专题因此不为皮洛萨编造统一聚居地、建国史或完整迁徙路径。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·皮洛萨（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1201—1214行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"艺术形象与现实人物","period":"1053年记录及1086年出版物以后","body":"一部1086年出版的东国漫画把缓慢与剑豪形象相联系，这是文化作品的塑造，不能当作该族群确有相同战斗能力的史料。安全报告同样只反映一次工作环境中的事件。\n\n罗德岛人事补充提到稀音的工作细致和成果，提醒读者不要把行动节奏直接等同于能力不足。她的摄影、研究与设备使用应回到个人档案继续读，不由族名推定技艺、寿命或心理特征。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·皮洛萨（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1201—1214行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·皮洛萨（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1201—1214行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"draco","name":"德拉克","en":"Draco","summary":"神话中的强大统治者与现实中的分散家系之间，存在需要逐一辨认的历史层次。","relatedRegions":["victoria","sargon"],"profileNames":["德拉克"],"relatedNames":[],"sourceLines":[1221,1226],"sections":[{"title":"分散家系与王权历史","period":"远古统治传统至维多利亚王权","body":"德拉克人数稀少，分布于不同地区，常以统治者或英雄出现在传说中。书中把部分故事视作历史改编，同时提醒，传奇中的飞行、喷火等叙述不能未经核实便当作普通生理能力。\n\n维多利亚德拉克王室的历史，为其实际政治地位提供了较清楚的线索。不同地区的家系有共同之处，也保留显著差异，不能把伦蒂尼姆的王室与塔拉盖尔王血脉视为完全同一个政治集团。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·德拉克（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1221—1226行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"统称形成与个体经历","period":"近千年的分类与交流","body":"“德拉克”成为较统一的称谓，本身经历了漫长的认同过程。各地的历史、习俗和旧称并没有随一个总称出现就全部消失，许多传说仍带着地方权力关系的痕迹。\n\n书中认可群体在部分身体条件和技艺适应性上具有优势，但这些不能代替个体档案。苇草与塔露拉的经历涉及不同的家庭、组织及政治选择，种族联系不等同于共同立场。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·德拉克（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1221—1226行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·德拉克（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1221—1226行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"lung","name":"龙","en":"Lung","summary":"炎氏、百氏与文字保存传统，构成炎国龙族认识自身历史的重要线索。","relatedRegions":["yan","lungmen"],"profileNames":["龙"],"relatedNames":[],"sourceLines":[1231,1237],"sections":[{"title":"炎氏与百氏后代","period":"炎国早期建制及其后","body":"龙主要生活在炎国。书中以炎氏及其继任者的历史解释“真龙”的政治与文化含义：皇帝继承这一称号，并不表示炎国其他自称龙的居民都是皇室。被炎氏赐姓的百氏后代，也构成这一认同的一部分。\n\n炎国保存了相当丰富的文献，作者因此认为其族源叙述比纯口述传说更有连续性。但古老记载仍有材料与解释层次，不能把所有传说自动写成现代人亲历的事实。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·龙（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1231—1237行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"文书传统与翻译差异","period":"长期史书编纂及对外交流","body":"记录、编纂和保存历史，是书中反复强调的社会传统。地方家族的来历与国家历史通过文字联系起来，龙族对祖先的认识也由文献传递，而非仅靠共同外貌。\n\n早期交流曾把维多利亚的德拉克同译作“龙”，造成双方长期误解。后来名称得到区分，旧绰号却可能保留。因此陈与老鲤的档案种族登记，不应与苇草等人的“德拉克”字段混用，也不能仅凭中文译名推定相同血统。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·龙（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1231—1237行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·龙（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1231—1237行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"kylin","name":"麒麟","en":"Kylin","summary":"炎国的术法教育与司法传统，保存了多个麒麟家族参与公共事务的历史。","relatedRegions":["yan"],"profileNames":["麒麟"],"relatedNames":[],"sourceLines":[1244,1248],"sections":[{"title":"早期侍卫与术法传承","period":"炎氏部族时期及后来的天师教育","body":"麒麟人口稀少，在炎国社会中具有较高威望。书中追溯到百氏之乱以前，一些麒麟已担任炎氏身边的侍卫与术师；有关雷池的叙述则以传说形式保存了祝氏先人的功绩。\n\n与传说不同，雷法的传承在书中有较明确的教育线索：天师府开设后，祝氏后人参与授业，原先家传的知识逐渐向不同种族的弟子开放。雷法因而不是麒麟独占的生理能力。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·麒麟（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1244—1248行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"家系、司法与个人责任","period":"历代朝廷至现代公共事务","body":"麒麟不都从事术法教学。书中还列举麟氏、法氏等家族与法律、惩戒事务的长期联系，解释这种族群形象如何成为地方平安与公正的象征。\n\n历史声望不等于每一位麒麟都具有同一官职、技艺或性格。惊蛰的工作和雷法表现，需要按她具体的教育、职责与档案阅读；专题不把家族传统扩写成适用于所有个体的固定人生。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·麒麟（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1244—1248行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·麒麟（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1244—1248行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"aegir","name":"阿戈尔","en":"Ægir","summary":"从海岸到内陆水体的迁徙，留下复杂而多样的族群；同名文明与每个人的国籍并非一回事。","relatedRegions":["aegir","iberia","higashi"],"profileNames":["阿戈尔"],"relatedNames":[],"sourceLines":[1249,1260],"sections":[{"title":"分布与水体依赖","period":"历史迁徙至陆地定居","body":"阿戈尔分布于泰拉沿海，也生活在内陆江河湖泊附近。书中依据迁徙、语言和神话线索，讨论部分群体由外缘向内陆移动的可能路线；这属于作者的族源研究，不能据此替每个家庭确认同一出发点。\n\n阿戈尔有许多体质不同的分支。亲近水体并不等于人人都能在水下呼吸，实际的水生适应性须分别认识。同名的海下文明和陆地档案中的种族字段，也不能直接等同于国籍。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·阿戈尔（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1249—1260行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"陆地生活与适应技术","period":"长期陆居及现代生活","body":"部分阿戈尔对失水较敏感，会使用保湿用品和补水装备适应干燥环境。书中举出的蒸馏设备说明，身体条件会带来具体的技术需求，却并不意味着个体无法在陆地生活。\n\n流明、棘刺、乌尔比安等人的处境连接了不同历史。专题仅据已公开种族字段建立档案链接；对没有公开种族登记的人物，不因外观或深海相关身份便替其填写档案。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·阿戈尔（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1249—1260行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·阿戈尔（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1249—1260行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"sankta","name":"萨科塔","en":"Sankta","summary":"律法、共感与圣城公民生活紧密相连，理解能力边界同样重要。","relatedRegions":["laterano"],"profileNames":["萨科塔"],"relatedNames":[],"sourceLines":[1261,1265],"sections":[{"title":"律法与共感生活","period":"拉特兰长期形成的共同生活","body":"萨科塔的光环和光翼，在书中被视作受律法庇护的象征。共感也由此进入日常交流，但作者明确承认，身为非萨科塔的观察者，他只能通过当事人的描述了解其运作，不能把旁观理解当作完整说明。\n\n书中将共感比作某种不必刻意调用的交流方式。这种比喻有助于说明日常经验，却不证明萨科塔能读取所有人的思想，更不能替代具体剧情中共感的限制与变化。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·萨科塔（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1261—1265行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"守护铳与社会实践","period":"信仰传统及现代成长","body":"守护铳在萨科塔生活中兼具武器和信仰意义。书中没有将拥有守护铳描述为一条强制所有人的成文规则，而是记录了其广泛存在的社会实践。\n\n萨科塔在拉特兰及境外承担不同职责，公民身份、共感联系和个人道德判断并不完全相同。能天使、送葬人与蕾缪安的经历可作对照；莫斯提马等人的公开字段仍应按档案保留，不用专题分类覆盖其特殊经历和未公开项目。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·萨科塔（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1261—1265行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·萨科塔（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1261—1265行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"sarkaz","name":"萨卡兹","en":"Sarkaz","summary":"提卡兹的家园记忆、长期流亡和多支氏族的差异，使萨卡兹无法被一个外貌或性格概括。","relatedRegions":["kazdel","sami","sargon"],"profileNames":["萨卡兹","鬼","阿纳萨"],"relatedNames":[],"sourceLines":[1275,1292],"sections":[{"title":"家园、流亡与多重氏族","period":"古代提卡兹历史至长期离散","body":"“萨卡兹”承载着失去家园与长期流亡的历史。书中介绍十王庭及若干非王庭氏族，同时指出，大多数现代萨卡兹具有多支氏族的混合血缘。角、尾或其他单一外貌因此不能概括所有成员。\n\n十王庭是特定历史与政治关系中的氏族称谓，不等于完整的人口分类，也不代表彼此始终团结。萨米的独眼巨人、卡兹戴尔的统治者和四处谋生的佣兵，保留着不同的社会经验。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·萨卡兹（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1275—1292行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"偏见、疾病与文化流失","period":"长期流亡至现代社会","body":"外界长期用残暴和危险解释萨卡兹，这些偏见又成为战争与排斥的理由。书中明确反对把道德判断强加于整个族群。不断迁徙也使许多传统难以保存，佣兵生活是生存处境带来的道路之一，不能被写成天生的职业。\n\n书中记载其感染矿石病的较高风险，同时保留研究解释与族群诅咒传说之间的区别。风险不等于每个人已感染，血脉技艺也不是统一能力。阿斯卡纶、逻各斯、泥岩等人的经历，要通过各自身体条件、家系和选择继续阅读。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·萨卡兹（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1275—1292行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·萨卡兹（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1275—1292行；印刷页范围据目录，未据原版影印逐页校勘。"}]}]};
